let VariationProcessor;

async function loadVariationProcessor() {
    try {
        return (await import('../src/variationprocessor.mjs')).VariationProcessor;
    } catch (error) {
        const requireFn = eval('typeof require !== "undefined" ? require : undefined');
        if (!requireFn) {
            throw error;
        }
        const path = requireFn('path');
        const esbuild = requireFn('esbuild');
        const Module = requireFn('module');
        const entry = path.resolve(__dirname, '../src/variationprocessor.mjs');
        const build = esbuild.buildSync({
            entryPoints: [entry],
            bundle: true,
            format: 'cjs',
            platform: 'node',
            write: false,
            define: { DEBUG: 'false' },
        });
        const loaded = new Module(entry, module);
        loaded.filename = entry;
        loaded.paths = Module._nodeModulePaths(path.dirname(entry));
        loaded._compile(build.outputFiles[0].text, entry);
        return loaded.exports.VariationProcessor;
    }
}

beforeAll(async () => {
    VariationProcessor = await loadVariationProcessor();
});

/* ------------------------------------------------------------------ helpers */

function axis(tag, minValue, defaultValue, maxValue) {
    return { tag, minValue, defaultValue, maxValue };
}

function point(x, y, lastPointOfContour = false) {
    return { x, y, onCurve: true, lastPointOfContour };
}

function makeFont(options = {}) {
    const {
        axes = [axis('wght', 0, 0, 1)],
        gvar,
        avar,
        cvar,
        cvt,
        hvar,
        coords = {},
        glyphs = {},
    } = options;

    const tables = { fvar: { axes } };
    if (gvar !== undefined) tables.gvar = gvar;
    if (avar !== undefined) tables.avar = avar;
    if (cvar !== undefined) tables.cvar = cvar;
    if (cvt !== undefined) tables.cvt = cvt;
    if (hvar !== undefined) tables.hvar = hvar;

    return {
        tables,
        variation: {
            get: jest.fn(() => ({ ...coords })),
        },
        glyphs: {
            get: jest.fn((index) => glyphs[index]),
        },
    };
}

function makeItemStore() {
    return {
        itemVariationSubtables: [
            {
                regionIndexes: [0],
                deltaSets: [[10], [20]],
            },
            {
                regionIndexes: [0],
                deltaSets: [[100]],
            },
        ],
        variationRegions: [
            {
                regionAxes: [{ startCoord: 0, peakCoord: 1, endCoord: 1 }],
            },
        ],
    };
}

