describe('VariationProcessor constructor and table helpers', () => {
    test('stores the supplied font on the instance', () => {
        const font = {};
        const processor = new VariationProcessor(font);

        expect(processor.font).toBe(font);
    });

    test('exposes the font tables through the accessor helpers', () => {
        const avar = { axisSegmentMaps: [] };
        const cvar = { headers: [] };
        const fvar = { axes: [] };
        const gvar = { glyphVariations: {} };
        const hvar = { itemVariationStore: {} };
        const font = { tables: { avar, cvar, fvar, gvar, hvar } };
        const processor = new VariationProcessor(font);

        expect(processor.avar()).toBe(avar);
        expect(processor.cvar()).toBe(cvar);
        expect(processor.fvar()).toBe(fvar);
        expect(processor.gvar()).toBe(gvar);
        expect(processor.hvar()).toBe(hvar);
    });

    test('returns undefined from table helpers for absent tables', () => {
        const processor = new VariationProcessor({ tables: {} });

        expect(processor.avar()).toBeUndefined();
        expect(processor.cvar()).toBeUndefined();
        expect(processor.fvar()).toBeUndefined();
        expect(processor.gvar()).toBeUndefined();
        expect(processor.hvar()).toBeUndefined();
    });
});

describe('normalizeCoordTags', () => {
    test('pads short tags with spaces in place', () => {
        const processor = new VariationProcessor(makeFont());
        const coords = { w: 1, abc: 2, wght: 3 };

        processor.normalizeCoordTags(coords);

        expect(coords).toEqual({ 'w   ': 1, 'abc ': 2, wght: 3 });
    });

    test('does not overwrite an already existing padded tag', () => {
        const processor = new VariationProcessor(makeFont());
        const coords = { abc: 1, 'abc ': 2 };

        processor.normalizeCoordTags(coords);

        expect(coords).toEqual({ 'abc ': 2 });
    });

    test('leaves tags of four or more characters untouched', () => {
        const processor = new VariationProcessor(makeFont());
        const coords = { wght: 100, weight: 200 };

        processor.normalizeCoordTags(coords);

        expect(coords).toEqual({ wght: 100, weight: 200 });
    });
});

describe('getNormalizedCoords', () => {
    const axes = [
        axis('wght', 100, 400, 900),
        axis('wdth', 50, 100, 200),
    ];

    test('normalizes above-axis values into the 0..1 range', () => {
        const processor = new VariationProcessor(makeFont({ axes }));

        const normalized = processor.getNormalizedCoords({ wght: 700, wdth: 150 });

        expect(normalized).toHaveLength(2);
        expect(normalized[0]).toBeCloseTo(0.6, 10);
        expect(normalized[1]).toBeCloseTo(0.5, 10);
    });

    test('normalizes below-axis values into the -1..0 range', () => {
        const processor = new VariationProcessor(makeFont({ axes }));

        const normalized = processor.getNormalizedCoords({ wght: 250 });

        expect(normalized[0]).toBeCloseTo(-0.5, 10);
        expect(normalized[1]).toBeCloseTo(0, 10);
    });

    test('returns -1 and 1 at the axis extremes', () => {
        const processor = new VariationProcessor(makeFont({ axes }));

        expect(processor.getNormalizedCoords({ wght: 100, wdth: 50 })[0]).toBeCloseTo(-1, 10);
        expect(processor.getNormalizedCoords({ wght: 900, wdth: 200 })[1]).toBeCloseTo(1, 10);
    });

    test('uses the default value for axes missing from the coordinates', () => {
        const processor = new VariationProcessor(makeFont({ axes }));

        const normalized = processor.getNormalizedCoords({ wght: 700 });

        expect(normalized[1]).toBeCloseTo(0, 10);
    });

    test('uses the default coordinate set when no coordinates are supplied', () => {
        const font = makeFont({ axes, coords: { wght: 650, wdth: 125 } });
        const processor = new VariationProcessor(font);

        const normalized = processor.getNormalizedCoords();

        expect(font.variation.get).toHaveBeenCalledTimes(1);
        expect(normalized[0]).toBeCloseTo(0.5, 10);
        expect(normalized[1]).toBeCloseTo(0.25, 10);
    });

    test('pads short incoming coordinate tags before looking axes up', () => {
        const font = makeFont({ axes: [axis('w   ', 100, 400, 900)] });
        const processor = new VariationProcessor(font);
        const coords = { w: 250 };

        const normalized = processor.getNormalizedCoords(coords);

        expect(normalized[0]).toBeCloseTo(-0.5, 10);
        expect(coords).toEqual({ 'w   ': 250 });
    });

    test('applies an avar mapping in the negative half of the axis', () => {
        const font = makeFont({
            axes: [axis('wght', -1, 0, 1)],
            coords: { wght: -0.75 },
            avar: {
                axisSegmentMaps: [{
                    axisValueMaps: [
                        { fromCoordinate: -1, toCoordinate: -0.5 },
                        { fromCoordinate: 0, toCoordinate: 0 },
                        { fromCoordinate: 1, toCoordinate: 1 },
                    ],
                }],
            },
        });
        const processor = new VariationProcessor(font);

        const normalized = processor.getNormalizedCoords();

        expect(normalized[0]).toBeCloseTo(-0.375, 10);
    });

    test('applies an avar mapping in the positive half of the axis', () => {
        const font = makeFont({
            axes: [axis('wght', -1, 0, 1)],
            coords: { wght: 0.5 },
            avar: {
                axisSegmentMaps: [{
                    axisValueMaps: [
                        { fromCoordinate: -1, toCoordinate: -1 },
                        { fromCoordinate: 0, toCoordinate: 0 },
                        { fromCoordinate: 1, toCoordinate: 0.5 },
                    ],
                }],
            },
        });
        const processor = new VariationProcessor(font);

        const normalized = processor.getNormalizedCoords();

        expect(normalized[0]).toBeCloseTo(0.25, 10);
    });
});

describe('deltaInterpolate', () => {
    test('does nothing when the target range is empty', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(0, 0), point(100, 100)];
        const points = [point(0, 0), point(110, 100)];

        processor.deltaInterpolate(2, 1, 0, 1, glyphPoints, points);

        expect(points).toEqual([point(0, 0), point(110, 100)]);
    });

    test('interpolates x and y deltas proportionally between two references', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(0, 0, false), point(50, 50, false), point(100, 100, true)];
        const points = [point(0, 0, false), point(50, 50, false), point(110, 100, true)];

        processor.deltaInterpolate(1, 1, 0, 2, glyphPoints, points);

        expect(points[1].x).toBeCloseTo(55, 10);
        expect(points[1].y).toBeCloseTo(50, 10);
    });

    test('sorts the reference points by coordinate before interpolating', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(100, 0), point(50, 0), point(0, 0)];
        const points = [point(110, 0), point(50, 0), point(0, 0)];

        processor.deltaInterpolate(1, 1, 0, 2, glyphPoints, points);

        expect(points[1].x).toBeCloseTo(55, 10);
    });

    test('leaves an axis untouched when coincident references move differently', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(10, 0), point(10, 0), point(10, 0)];
        const points = [point(12, 0), point(10, 0), point(20, 0)];

        processor.deltaInterpolate(1, 1, 0, 2, glyphPoints, points);

        expect(points[1].x).toBe(10);
    });
});

describe('deltaShift', () => {
    test('returns early when the reference point has no delta', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(0, 0), point(10, 10), point(20, 20)];
        const points = glyphPoints.map((p) => ({ ...p }));

        processor.deltaShift(0, 2, 1, glyphPoints, points);

        expect(points).toEqual(glyphPoints);
    });

    test('translates every point of a contour except the reference point', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(0, 0), point(10, 10), point(20, 20)];
        const points = [point(5, 3), point(15, 13), point(25, 23)];

        processor.deltaShift(0, 2, 1, glyphPoints, points);

        expect(points).toEqual([point(5, 3), point(15, 13), point(25, 23)]);
    });

    test('applies both x and y deltas to non-reference points', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(0, 0), point(10, 10), point(20, 20)];
        const points = [point(3, -2), point(15, 13), point(23, 18)];

        processor.deltaShift(1, 2, 0, glyphPoints, points);

        expect(points[1]).toEqual(point(18, 8));
        expect(points[2]).toEqual(point(26, 13));
    });
});

describe('interpolatePoints', () => {
    test('is a no-op for an empty point list', () => {
        const processor = new VariationProcessor(makeFont());

        expect(processor.interpolatePoints([], [], [])).toBeUndefined();
    });

    test('leaves a contour without any deltas unchanged', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(0, 0), point(10, 10, true)];
        const points = glyphPoints.map((p) => ({ ...p }));

        processor.interpolatePoints(points, glyphPoints, [false, false]);

        expect(points).toEqual(glyphPoints);
    });

    test('shifts the entire contour when only one point has a delta', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(0, 0), point(50, 0), point(100, 0, true)];
        const points = [point(0, 0), point(53.5, 0), point(100, 0, true)];

        processor.interpolatePoints(points, glyphPoints, [false, true, false]);

        expect(points).toEqual([point(3.5, 0), point(53.5, 0), point(103.5, 0, true)]);
    });

    test('interpolates intermediate points between two deltas', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [point(0, 0), point(50, 0), point(100, 0, true)];
        const points = [point(0, 0), point(50, 0), point(105, 0, true)];

        processor.interpolatePoints(points, glyphPoints, [true, false, true]);

        expect(points[0]).toEqual(point(0, 0));
        expect(points[1]).toEqual(point(52.5, 0));
        expect(points[2]).toEqual(point(105, 0, true));
    });

    test('wraps interpolation around the start of a contour', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [
            point(0, 0),
            point(10, 0),
            point(20, 0),
            point(30, 0, true),
        ];
        const points = [
            point(0, 0),
            point(15, 0),
            point(20, 0),
            point(35, 0, true),
        ];

        processor.interpolatePoints(points, glyphPoints, [false, true, false, true]);

        expect(points.map((p) => p.x)).toEqual([5, 15, 25, 35]);
    });

    test('processes multiple contours independently', () => {
        const processor = new VariationProcessor(makeFont());
        const glyphPoints = [
            point(0, 0),
            point(10, 0, true),
            point(20, 0),
            point(30, 0, true),
        ];
        const points = [
            point(0, 0),
            point(10, 0, true),
            point(20, 0),
            point(35, 0, true),
        ];

        processor.interpolatePoints(points, glyphPoints, [false, false, false, true]);

        expect(points.map((p) => p.x)).toEqual([0, 10, 25, 35]);
    });
});

