    function compositeFixture() {
        const componentGlyph0 = { index: 0, points: [point(1, 1), point(2, 2)] };
        const componentGlyph1 = { index: 1, points: [point(10, 20), point(30, 40)] };
        const font = makeFont({ glyphs: { 0: componentGlyph0, 1: componentGlyph1 } });
        const processor = new VariationProcessor(font);
        const glyph = {
            index: 5,
            isComposite: true,
            components: [
                {
                    glyphIndex: 0, xScale: 2, scale01: 0, scale10: 0, yScale: 2, dx: 1, dy: 1,
                },
                {
                    glyphIndex: 1, xScale: 1, scale01: 0, scale10: 0, yScale: 1, dx: 0, dy: 0,
                },
            ],
        };
        return { processor, glyph, componentGlyph0, componentGlyph1 };
    }

    test('adds a scaled delta to the targeted component offset', () => {
        const { processor, glyph } = compositeFixture();
        const transformedPoints = [point(0, 0), point(0, 0), point(0, 0), point(0, 0)];
        const header = { deltas: [3], deltasY: [-2] };

        processor.transformComponents(glyph, transformedPoints, { wght: 1 }, [1], header, 0.5);

        expect(transformedPoints).toEqual([
            point(3, 3),
            point(5, 5),
            point(12, 19),
            point(32, 39),
        ]);
        expect(glyph.components[1].dx).toBe(0);
        expect(glyph.components[1].dy).toBe(0);
    });

    test('does not modify the original component descriptors', () => {
        const { processor, glyph } = compositeFixture();
        const transformedPoints = [point(0, 0), point(0, 0), point(0, 0), point(0, 0)];

        processor.transformComponents(glyph, transformedPoints, {}, [0], { deltas: [10], deltasY: [10] }, 1);

        expect(glyph.components[0].dx).toBe(1);
        expect(glyph.components[0].dy).toBe(1);
    });
});

