'use strict';

const path = require('path');
const { pathToFileURL } = require('url');

let cmapModule;
let parseModule;

beforeAll(async () => {
    cmapModule = await import(pathToFileURL(path.join(__dirname, '../../src/tables/cmap.mjs')).href);
    parseModule = await import(pathToFileURL(path.join(__dirname, '../../src/parse.mjs')).href);
