// ---------------------------------------------------------------------------
// Binary fixture helpers
// ---------------------------------------------------------------------------

function toDataView(bytes) {
    return new DataView(new Uint8Array(bytes).buffer);
}

function writeUInt24(view, offset, value) {
    view.setUint8(offset, (value >> 16) & 0xFF);
    view.setUint16(offset + 1, value & 0xFFFF);
}

/**
 * Builds a complete cmap table (the table header plus the supplied sub-tables)
 * and lays the sub-tables out contiguously after the encoding records.
 */
function buildCmap(subtables) {
    const headerSize = 4 + subtables.length * 8;
    let totalSize = headerSize;
    const offsets = subtables.map((subtable) => {
        const offset = totalSize;
        totalSize += subtable.data.length;
        return offset;
    });

    const bytes = new Uint8Array(totalSize);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, 0);
    view.setUint16(2, subtables.length);
    subtables.forEach((subtable, i) => {
        view.setUint16(4 + i * 8, subtable.platformID);
        view.setUint16(6 + i * 8, subtable.encodingID);
        view.setUint32(8 + i * 8, offsets[i]);
        bytes.set(subtable.data, offsets[i]);
    });
    return view;
}

function format0Subtable({ indexMap = [], language = 0, length = 262, padding = 0 } = {}) {
    const bytes = new Uint8Array(6 + 256 + padding);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, 0); // format
    view.setUint16(2, length);
    view.setUint16(4, language);
    for (let i = 0; i < 256; i += 1) {
        bytes[6 + i] = indexMap[i] || 0;
    }
    return bytes;
}

function format4Subtable({ segments, glyphs = [], language = 0 }) {
    const segCount = segments.length;
    const length = 16 + segCount * 8 + glyphs.length * 2;
    const bytes = new Uint8Array(length);
    const view = new DataView(bytes.buffer);

    view.setUint16(0, 4); // format
    view.setUint16(2, length);
    view.setUint16(4, language);
    view.setUint16(6, segCount * 2);
    // searchRange, entrySelector and rangeShift are not used by the parser.

    segments.forEach((segment, i) => {
        view.setUint16(14 + i * 2, segment.end);
        view.setUint16(16 + segCount * 2 + i * 2, segment.start);
        view.setInt16(16 + segCount * 4 + i * 2, segment.delta);
        view.setUint16(16 + segCount * 6 + i * 2, segment.rangeOffset || 0);
    });
    glyphs.forEach((glyph, i) => {
        view.setUint16(16 + segCount * 8 + i * 2, glyph);
    });
    return bytes;
}

function format12Subtable(groups, { format = 12, language = 0, reserved = 0 } = {}) {
    const bytes = new Uint8Array(16 + groups.length * 12);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, format);
    view.setUint16(2, reserved);
    view.setUint32(4, bytes.length);
    view.setUint32(8, language);
    view.setUint32(12, groups.length);
    groups.forEach((group, i) => {
        view.setUint32(16 + i * 12, group.start);
        view.setUint32(20 + i * 12, group.end);
        view.setUint32(24 + i * 12, group.glyph);
    });
    return bytes;
}

/**
 * Builds a format 14 sub-table. Offsets inside the sub-table are
 * automatically laid out after the variable-selector records.
 */
function format14Subtable(records) {
    const recordsStart = 10;
    const recordsSize = records.length * 11;
    let cursor = recordsStart + recordsSize;

    const defaultOffsets = records.map((record) => {
        if (!record.defaultUVS) return 0;
        const offset = cursor;
        cursor += 4 + record.defaultUVS.ranges.length * 5;
        return offset;
    });
    const nonDefaultOffsets = records.map((record) => {
        if (!record.nonDefaultUVS) return 0;
        const offset = cursor;
        cursor += 4 + record.nonDefaultUVS.mappings.length * 5;
        return offset;
    });

    const bytes = new Uint8Array(cursor);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, 14); // format
    view.setUint32(2, cursor); // length
    view.setUint32(6, records.length);

    records.forEach((record, i) => {
        const base = recordsStart + i * 11;
        writeUInt24(view, base, record.varSelector);
        view.setUint32(base + 3, defaultOffsets[i]);
        view.setUint32(base + 7, nonDefaultOffsets[i]);
    });

    records.forEach((record, i) => {
        if (record.defaultUVS) {
            const offset = defaultOffsets[i];
            view.setUint32(offset, record.defaultUVS.ranges.length);
            let p = offset + 4;
            record.defaultUVS.ranges.forEach((range) => {
                writeUInt24(view, p, range.startUnicodeValue);
                view.setUint8(p + 3, range.additionalCount);
                p += 5;
            });
        }
        if (record.nonDefaultUVS) {
            const offset = nonDefaultOffsets[i];
            view.setUint32(offset, record.nonDefaultUVS.mappings.length);
            let p = offset + 4;
            record.nonDefaultUVS.mappings.forEach(([unicodeValue, glyphID]) => {
                writeUInt24(view, p, unicodeValue);
                view.setUint16(p + 3, glyphID);
                p += 5;
            });
        }
    });

    return bytes;
}

function glyphSet(glyphs) {
    return {
        length: glyphs.length,
        get(index) {
            return glyphs[index];
        }
    };
}

function tableField(table, name) {
    const field = table.fields.find((candidate) => candidate.name === name);
    return field === undefined ? undefined : field.value;
}

function encodeToDataView(table) {
    return toDataView(table.encode());
}

