// Module contract
// ---------------------------------------------------------------------------

describe('cmap module exports', () => {
    test('exposes parsers and the table builder', () => {
        expect(typeof cmapModule.default.parse).toBe('function');
        expect(typeof cmapModule.default.make).toBe('function');
        expect(typeof cmapModule.parseCmapTableFormat0).toBe('function');
        expect(typeof cmapModule.parseCmapTableFormat14).toBe('function');
        expect(typeof cmapModule.makeCmapTable).toBe('function');
    });
