// parseCmapTable
// ---------------------------------------------------------------------------

describe('parseCmapTable', () => {
    test('rejects a non-zero table version', () => {
        const bytes = new Uint8Array([0, 1, 0, 0]);
        expect(() => cmapModule.default.parse(toDataView(bytes), 0)).toThrow(
            'cmap table version should be 0.'
        );
    });

    test('throws when no supported sub-table exists', () => {
        const data = buildCmap([
            { platformID: 2, encodingID: 0, data: format12Subtable([{ start: 65, end: 65, glyph: 1 }]) }
