        prefixed.set(new Uint8Array(table.buffer), 40);

        const parsed = cmapModule.default.parse(toDataView(prefixed), 40);
        expect(parsed.glyphIndexMap).toEqual({ 65: 1, 66: 2 });
    });

    test('prefers the Unicode format 12 sub-table over a format 4 sub-table', () => {
        const bmpTable = format4Subtable({
            segments: [
                { start: 65, end: 65, delta: -64, rangeOffset: 0 },
                terminatorSegment
            ]
        });
        const fullTable = format12Subtable([{ start: 65, end: 65, glyph: 9 }], { language: 3 });
        const data = buildCmap([
            { platformID: 3, encodingID: 1, data: bmpTable },
            { platformID: 3, encodingID: 10, data: fullTable }
        ]);

        const parsed = cmapModule.default.parse(data, 0);
        expect(parsed).toMatchObject({
            format: 12,
            language: 3,
            groupCount: 1,
            glyphIndexMap: { 65: 9 }
        });
    });

    test('accepts a platform 0 Unicode sub-table', () => {
        const data = buildCmap([
            {
                platformID: 0,
                encodingID: 4,
                data: format12Subtable([{ start: 0x1F600, end: 0x1F601, glyph: 4 }])
            }
        ]);

        const parsed = cmapModule.default.parse(data, 0);
        expect(parsed.format).toBe(12);
        expect(parsed.glyphIndexMap).toEqual({ 128512: 4, 128513: 5 });
    });
});

