        const data = buildCmap([
            {
                platformID: 3,
                encodingID: 1,
                data: format4Subtable({
                    language: 7,
                    segments: [
                        { start: 0x41, end: 0x43, delta: -64, rangeOffset: 0 },
                        terminatorSegment
                    ]
                })
            }
        ]);

        const parsed = cmapModule.default.parse(data, 0);
        expect(parsed).toMatchObject({
            version: 0,
            numTables: 1,
            format: 4,
            length: 32,
