            segCount: 2,
            glyphIndexMap: { 65: 1, 66: 2, 67: 3 }
        });
        expect(parsed.glyphIndexMap[0xFFFF]).toBeUndefined();
    });

    test('uses the glyph index array when idRangeOffset is non-zero', () => {
        const data = buildCmap([
