function buildCmapTable(entries) {
    // entries: [{platformID, encodingID, data: Uint8Array}]
    const headerSize = 4 + entries.length * 8;
    const totalSize = entries.reduce((size, entry) => size + entry.data.length, headerSize);
    const bytes = new Uint8Array(totalSize);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, 0, false);
    view.setUint16(2, entries.length, false);

    let offset = headerSize;
    entries.forEach((entry, index) => {
        view.setUint16(4 + index * 8, entry.platformID, false);
        view.setUint16(6 + index * 8, entry.encodingID, false);
        view.setUint32(8 + index * 8, offset, false);
        bytes.set(entry.data, offset);
        offset += entry.data.length;
    });
    return view;
}

function makeFormat4Subtable({segments, glyphIds = [], language = 0}) {
    const segCount = segments.length;
    const length = 16 + segCount * 8 + glyphIds.length * 2;
    const bytes = new Uint8Array(length);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, 4, false);
    view.setUint16(2, length, false);
    view.setUint16(4, language, false);
    view.setUint16(6, segCount * 2, false);
    view.setUint16(8, 0, false);
    view.setUint16(10, 0, false);
    view.setUint16(12, 0, false);

    segments.forEach((segment, i) => {
        view.setUint16(14 + i * 2, segment.end, false);
        view.setUint16(16 + segCount * 2 + i * 2, segment.start, false);
        view.setInt16(16 + segCount * 4 + i * 2, segment.delta, false);
        view.setUint16(16 + segCount * 6 + i * 2, segment.rangeOffset, false);
    });
    glyphIds.forEach((glyphId, i) => {
        view.setUint16(16 + segCount * 8 + i * 2, glyphId, false);
    });
    return bytes;
}

function makeFormat12Subtable(groups, {format = 12, language = 0, reserved = 0} = {}) {
    const bytes = new Uint8Array(16 + groups.length * 12);
    const view = new DataView(bytes.buffer);
    view.setUint16(0, format, false);
    view.setUint16(2, reserved, false);
    view.setUint32(4, bytes.length, false);
    view.setUint32(8, language, false);
    view.setUint32(12, groups.length, false);
    groups.forEach((group, i) => {
        view.setUint32(16 + i * 12, group.start, false);
        view.setUint32(20 + i * 12, group.end, false);
        view.setUint32(24 + i * 12, group.glyphId, false);
