        expect(cmap.glyphIndexMap[161]).toBe(33);
    });

    it('accepts platform 0 Unicode subtable records', () => {
        const data = buildCmapTable([{platformID: 0, encodingID: 3, data: simpleFormat4()}]);
        const cmap = parseCmapTable(data, 0);

        expect(cmap.format).toBe(4);
        expect(cmap.glyphIndexMap[66]).toBe(2);
    });

    it('prefers the last supported subtable record when several are present', () => {
        const low = makeFormat4Subtable({
            segments: [{start: 0x41, end: 0x41, delta: -64, rangeOffset: 0},
                {start: 0xFFFF, end: 0xFFFF, delta: 1, rangeOffset: 0}]
        });
        const high = makeFormat4Subtable({
            segments: [{start: 0x41, end: 0x41, delta: -58, rangeOffset: 0},
                {start: 0xFFFF, end: 0xFFFF, delta: 1, rangeOffset: 0}]
        });
        const data = buildCmapTable([
            {platformID: 3, encodingID: 1, data: low},
            {platformID: 0, encodingID: 4, data: high}
        ]);
        const cmap = parseCmapTable(data, 0);

        expect(cmap.glyphIndexMap[0x41]).toBe(7);
    });

    it('parses format 14 variation selectors as a supplement to format 4', () => {
        const data = buildCmapTable([
            {platformID: 3, encodingID: 1, data: simpleFormat4()},
            {platformID: 0, encodingID: 5, data: makeFormat14Subtable()}
        ]);
        const cmap = parseCmapTable(data, 0);

        expect(cmap.format).toBe(4);
        expect(cmap.glyphIndexMap[0x42]).toBe(2);
        expect(cmap.varSelectorList[0xFE00]).toEqual({
            varSelector: 0xFE00,
            defaultUVS: {
                ranges: [{startUnicodeValue: 0x41, additionalCount: 2}]
            }
        });
        expect(cmap.varSelectorList[0xFE01]).toEqual({
            varSelector: 0xFE01,
            nonDefaultUVS: {
                uvsMappings: {
                    0x50: {unicodeValue: 0x50, glyphID: 100},
                    0x51: {unicodeValue: 0x51, glyphID: 101}
                }
            }
        });
    });

    it('ignores a platform 0/encoding 5 record that is not actually format 14', () => {
        const notFormat14 = makeFormat4Subtable({
            segments: [{start: 0x41, end: 0x41, delta: -64, rangeOffset: 0},
                {start: 0xFFFF, end: 0xFFFF, delta: 1, rangeOffset: 0}]
        });
        const data = buildCmapTable([
            {platformID: 3, encodingID: 1, data: simpleFormat4()},
            {platformID: 0, encodingID: 5, data: notFormat14}
        ]);
        const cmap = parseCmapTable(data, 0);

        expect(cmap.format).toBe(4);
        expect(cmap.varSelectorList).toBeUndefined();
    });

    it('throws when only an unsupported/format-14-only subtable is available', () => {
        const data = buildCmapTable([{platformID: 0, encodingID: 5, data: makeFormat14Subtable()}]);
        expect(() => parseCmapTable(data, 0)).toThrow('No valid cmap sub-tables found.');
    });

    it('throws for a non-zero cmap version', () => {
        const bytes = new Uint8Array(12);
        const view = new DataView(bytes.buffer);
        view.setUint16(0, 1, false);
        view.setUint16(2, 0, false);

        expect(() => parseCmapTable(view, 0)).toThrow('cmap table version should be 0.');
    });

    it('throws a descriptive error for an unsupported subtable format', () => {
        const bytes = new Uint8Array(4 + 8 + 8);
        const view = new DataView(bytes.buffer);
        view.setUint16(0, 0, false);
        view.setUint16(2, 1, false);
        view.setUint16(4, 3, false);
        view.setUint16(6, 1, false);
        view.setUint32(8, 12, false);
        view.setUint16(12, 6, false); // format 6
        view.setUint16(14, 10, false); // subtable length

        expect(() => parseCmapTable(view, 0)).toThrow(
            'Only format 0 (platformId 1, encodingId 0), 4, 12 and 14 cmap tables are supported ' +
            '(found format 6, platformId 3, encodingId 1).'
        );
    });
});

describe('parseCmapTableFormat0 (exported helper)', () => {
    it('decodes the index map when given a parser positioned after the format field', () => {
        const indexMap = [];
        indexMap[0x41] = 4;
        indexMap[0x80] = 12;
        const subtable = makeFormat0Subtable({indexMap, language: 1});
        const parser = new Parser(dataViewOf(subtable), 0);
        parser.parseUShort(); // consume the format field

        const cmap = {};
        parseCmapTableFormat0(cmap, parser, 1, 0);

        expect(cmap.length).toBe(262);
        expect(cmap.language).toBe(0);
        expect(cmap.glyphIndexMap[0x41]).toBe(4);
        expect(cmap.glyphIndexMap[196]).toBe(12);
    });
});

describe('parseCmapTableFormat14 (exported helper)', () => {
    it('reads default and non-default UVS tables', () => {
        const subtable = makeFormat14Subtable();
        const parser = new Parser(dataViewOf(subtable), 0);
        parser.parseUShort(); // consume the format field

        const cmap = {};
        parseCmapTableFormat14(cmap, parser);

        expect(Object.keys(cmap.varSelectorList)).toEqual(['65024', '65025']);
        expect(cmap.varSelectorList[0xFE00].defaultUVS.ranges[0]).toEqual({
            startUnicodeValue: 0x41,
            additionalCount: 2
        });
        expect(cmap.varSelectorList[0xFE01].nonDefaultUVS.uvsMappings[0x51]).toEqual({
            unicodeValue: 0x51,
            glyphID: 101
        });
    });
});

// ---------------------------------------------------------------------------
// make (makeCmapTable)
// ---------------------------------------------------------------------------

describe('makeCmapTable', () => {
    it('emits a terminator-only format 4 table for an empty glyph set', () => {
        const cmap = makeCmapTable(glyphSet([]));

        expect(cmap).toMatchObject({
            version: 0,
            numTables: 1,
            platformID: 3,
            encodingID: 1,
            offset: 12,
            format: 4,
            language: 0,
            segCountX2: 2,
            searchRange: 2,
            entrySelector: 0,
            rangeShift: 0,
            cmap4Length: 24
        });
        expect(cmap.segments).toEqual([
            {end: 0xFFFF, start: 0xFFFF, delta: 1, offset: 0}
        ]);
    });

    it('creates format 4 segments and merges runs with the same delta', () => {
        const glyphs = glyphSet([
            {unicode: 0, unicodes: [0]},
            {unicode: 32, unicodes: [32]},
            {unicode: 65, unicodes: [65, 66]},
            {unicode: 67, unicodes: [67]}
        ]);
        const cmap = makeCmapTable(glyphs);

        expect(cmap.numTables).toBe(1);
        expect(cmap.format).toBe(4);
        expect(cmap.offset).toBe(12);
        expect(cmap.segments).toEqual([
            {end: 0, start: 0, delta: 0, offset: 0, glyphIndex: 0},
            {end: 32, start: 32, delta: -31, offset: 0, glyphIndex: 1},
            {end: 65, start: 65, delta: -63, offset: 0, glyphIndex: 2},
            {end: 67, start: 66, delta: -64, offset: 0, glyphIndex: 2},
            {end: 0xFFFF, start: 0xFFFF, delta: 1, offset: 0}
        ]);
        expect(cmap.segCountX2).toBe(10);
        expect(cmap.searchRange).toBe(8);
        expect(cmap.entrySelector).toBe(2);
        expect(cmap.rangeShift).toBe(2);
        expect(cmap.cmap4Length).toBe(56);
    });

    it('adds a format 12 subtable when a glyph uses a supplementary-plane codepoint', () => {
        const glyphs = glyphSet([
            {unicode: 0, unicodes: [0]},
            {unicode: 0x1F600, unicodes: [0x1F600]},
            {unicode: 65, unicodes: [65]}
        ]);
        const cmap = makeCmapTable(glyphs);

        expect(cmap).toMatchObject({
            numTables: 2,
            offset: 20,
            format: 4,
            cmap12PlatformID: 3,
            cmap12EncodingID: 10,
            cmap12Length: 52,
            cmap12Language: 0,
            cmap12nGroups: 3,
            segCountX2: 6,
            searchRange: 4,
            entrySelector: 1,
            rangeShift: 2,
            cmap4Length: 40
        });
        expect(cmap.cmap12Offset).toBe(60);
        expect(cmap.fields.filter((field) => field.name.startsWith('cmap12Start_'))).toEqual([
            {name: 'cmap12Start_0', type: 'ULONG', value: 0},
            {name: 'cmap12Start_1', type: 'ULONG', value: 65},
            {name: 'cmap12Start_2', type: 'ULONG', value: 128512}
        ]);
    });

    it('does not merge non-adjacent codepoints', () => {
        const glyphs = glyphSet([
            {unicode: 65, unicodes: [65]},
            {unicode: 67, unicodes: [67]}
        ]);
        const cmap = makeCmapTable(glyphs);
        const mappingSegments = cmap.segments.slice(0, -1);

        expect(mappingSegments).toHaveLength(2);
        expect(mappingSegments[0]).toMatchObject({start: 65, end: 65});
        expect(mappingSegments[1]).toMatchObject({start: 67, end: 67});
    });

    it('encodes a table whose size matches sizeOf and can be parsed back (format 4)', () => {
        const glyphs = glyphSet([
            {unicode: 0, unicodes: [0]},
            {unicode: 32, unicodes: [32]},
            {unicode: 65, unicodes: [65, 66]},
            {unicode: 67, unicodes: [67]}
        ]);
        const cmap = makeCmapTable(glyphs);
        const bytes = cmap.encode();

        expect(bytes).toHaveLength(cmap.sizeOf());
        const parsed = parseCmapTable(dataViewOf(bytes), 0);
        expect(parsed.format).toBe(4);
        expect(parsed.cmap4Length).toBeUndefined();
        expect(parsed.glyphIndexMap).toEqual({
            0: 0, 32: 1, 65: 2, 66: 2, 67: 3
        });
    });

    it('encodes a supplementary table so that it round-trips through format 12', () => {
        const glyphs = glyphSet([
            {unicode: 0, unicodes: [0]},
            {unicode: 0x1F600, unicodes: [0x1F600]},
            {unicode: 65, unicodes: [65]}
        ]);
        const cmap = makeCmapTable(glyphs);
        const bytes = cmap.encode();

        expect(bytes).toHaveLength(cmap.sizeOf());
        const parsed = parseCmapTable(dataViewOf(bytes), 0);
        expect(parsed.format).toBe(12);
        expect(parsed.groupCount).toBe(3);
        expect(parsed.glyphIndexMap).toEqual({0: 0, 65: 2, 128512: 1});
    });

    it('keeps a BMP table within the maximum format 4 segment budget', () => {
        const glyphs = [];
        for (let i = 0; i < 8188; i += 1) {
            const code = i * 2;
            glyphs.push({unicode: code, unicodes: [code]});
        }
        const cmap = makeCmapTable(glyphSet(glyphs));

        expect(cmap.numTables).toBe(1);
        expect(cmap.format).toBe(4);
        expect(cmap.cmap4Length).toBe(65528);
        expect(cmap.cmap4Length).toBeLessThanOrEqual(0xFFFF);
        expect(cmap.segCountX2).toBe(8189 * 2);
    });

    it('falls back to a terminator-only format 4 when the BMP segment budget overflows', () => {
        const glyphs = [];
        for (let i = 0; i < 8190; i += 1) {
            const code = i * 2;
            glyphs.push({unicode: code, unicodes: [code]});
        }
        const cmap = makeCmapTable(glyphSet(glyphs));

        expect(cmap.numTables).toBe(2);
        expect(cmap.offset).toBe(20);
        expect(cmap.cmap12PlatformID).toBe(3);
        expect(cmap.cmap12EncodingID).toBe(10);
        expect(cmap.cmap4Length).toBe(24);
        expect(cmap.segCountX2).toBe(2);
        expect(cmap.cmap12nGroups).toBe(8190);
        expect(cmap.cmap12Offset).toBe(44);
        expect(cmap.fields.filter((field) => field.name.startsWith('end_')).length).toBe(1);
        expect(cmap.fields.find((field) => field.name === 'end_8190').value).toBe(0xFFFF);
    });
});
